<script lang="ts">
  import type { SettingsSnapshot, SettingValue } from './settings';
  import MappingPanel,{type MappingSnapshot,type MappingChange} from './MappingPanel.svelte';
  import {command,desktop} from './api';
  import {createRequestGate} from './requestGate.js';
  import {onDestroy,tick} from 'svelte';
  import Icon from './Icon.svelte';
  import AtkDpi from './AtkDpi.svelte';
  import AtkMacro from './AtkMacro.svelte';
  import KeyboardLighting from './KeyboardLighting.svelte';
  import AtkParameters from './AtkParameters.svelte';
  import Overlay from './Overlay.svelte';
  import {performanceFields,settingValueLabel} from './settingsPresentation.js';
  const requests=createRequestGate();
  let dpi:AtkDpi|undefined=$state();let macro:AtkMacro|undefined=$state();let lighting:KeyboardLighting|undefined=$state();
  let dpiLoaded=$state(false);let macroLoaded=$state(false);let lightingLoaded=$state(false);
  let parameters:AtkParameters|undefined=$state();let parametersLoaded=$state(false);
  const extraDirty=()=>!!dpi?.hasUnsavedChanges()||!!macro?.hasUnsavedChanges()||!!lighting?.hasUnsavedChanges()||!!parameters?.hasUnsavedChanges();
  const extraPending=()=>!!dpi?.isOperationPending()||!!macro?.isOperationPending()||!!lighting?.isOperationPending()||!!parameters?.isOperationPending();
  let tab=$state('mapping');let mappingLoaded=$state(false);let mappings:MappingPanel|undefined=$state();
  let officialBusy=$state(false);let officialError=$state('');
  function selectSection(next:string){tab=next;if(next==='mapping')mappingLoaded=true;if(next==='dpi')dpiLoaded=true;if(next==='macro')macroLoaded=true;if(next==='lighting')lightingLoaded=true;if(next==='parameters')parametersLoaded=true;}
  async function official(){if(officialBusy||sample||!desktop)return;officialBusy=true;officialError='';try{await command('open_official',{brand:keyboard?'mchose':'atk'});}catch(e){officialError=message(e);}finally{officialBusy=false;}}
  const loadMappings=(id:string,layer='Default')=>mappingAdapter?mappingAdapter.load(id,layer):model.includes('KX75')?command<MappingSnapshot>('read_keyboard_mappings',{deviceId:id,layer}):command<MappingSnapshot>('read_button_mappings',{deviceId:id});
  const applyMapping=(id:string,change:MappingChange)=>mappingAdapter?mappingAdapter.apply(id,change):model.includes('KX75')?command<MappingSnapshot>('apply_keyboard_mapping',{deviceId:id,change:{layer:change.layer||'Default',keyId:change.buttonId,action:change.action,expectedState:change.expectedState}}):command<MappingSnapshot>('apply_button_mapping',{deviceId:id,change});
  let {open,model,deviceId,onclose,load,apply,mappingAdapter,sample=false}:{open:boolean;model:string;deviceId:string|null;onclose:()=>void;load:(id:string)=>Promise<SettingsSnapshot>;apply:(id:string,changes:Record<string,SettingValue>)=>Promise<SettingsSnapshot>;mappingAdapter?:{load:(id:string,layer?:string)=>Promise<MappingSnapshot>;apply:(id:string,change:MappingChange)=>Promise<MappingSnapshot>};sample?:boolean}=$props();
  let snapshot=$state<SettingsSnapshot|null>(null);
  const keyboard=$derived(model.includes('KX75'));
  const sections=$derived(keyboard?[{id:'mapping',label:'按键配置',icon:'keyboard'},{id:'lighting',label:'灯光设置',icon:'sun'},{id:'performance',label:'性能设置',icon:'settings'},{id:'other',label:'其他设置',icon:'grid'}]:[{id:'mapping',label:'按键功能',icon:'mouse'},{id:'macro',label:'快捷指令',icon:'keyboard'},{id:'dpi',label:'DPI 设置',icon:'grid'},{id:'performance',label:'性能设置',icon:'settings'},{id:'parameters',label:'参数设置',icon:'settings'},{id:'profiles',label:'配置管理',icon:'grid'},{id:'other',label:'其他设置',icon:'devices'}]);
  const visibleFields=$derived(performanceFields(snapshot?.fields??[],keyboard));
  let draft=$state<Record<string,SettingValue>>({});
  let busy=$state(false);let error=$state('');let success=$state('');let loadedId='';
  let confirmed=$state(false);
  let discardOpen=$state(false);
  let continueButton=$state<HTMLButtonElement>();let discardReturn:HTMLElement|null=null;
  function focusWorkspaceClose(node:HTMLButtonElement){node.autofocus=true;if(node.closest('dialog')?.open)node.focus();}
  $effect(()=>{if(discardOpen)void tick().then(()=>{if(discardOpen)continueButton?.focus();});});
  function continueEditing(){discardOpen=false;void tick().then(()=>discardReturn?.focus());}
  function resetPanels(){requests.invalidate();loadedId='';snapshot=null;draft={};confirmed=false;discardOpen=false;mappingLoaded=false;dpiLoaded=false;macroLoaded=false;lightingLoaded=false;parametersLoaded=false;tab='mapping';error='';success='';officialError='';}
  function finishClose(){resetPanels();onclose();}
  export function requestClose(){if(busy||mappings?.isOperationPending()||extraPending())return;if(dirty||mappings?.hasUnsavedChanges()||extraDirty()){if(!discardOpen)discardReturn=document.activeElement instanceof HTMLElement?document.activeElement:null;discardOpen=true;return;}finishClose();}
  export function hasUnsavedChanges(){return dirty||busy||!!mappings?.hasUnsavedChanges()||extraDirty();}
  export function isOperationPending(){return busy||!!mappings?.isOperationPending()||extraPending();}
  const changes=$derived(Object.fromEntries(Object.entries(draft).filter(([key,value])=>snapshot?.fields.some(f=>f.key===key&&f.available&&f.value!==value))));
  const dirty=$derived(Object.keys(changes).length>0);
  const invalid=$derived(Object.entries(changes).some(([key,value])=>{const f=snapshot?.fields.find(f=>f.key===key);if(!f||!f.available)return true;return (typeof value==='number'&&(!Number.isFinite(value)||(f.min!=null&&value<f.min)||(f.max!=null&&value>f.max)||(f.step!=null&&f.step>0&&Math.abs((value-(f.min??0))/f.step-Math.round((value-(f.min??0))/f.step))>1e-8)))||!!(f.options?.length&&!f.options.some(o=>o.value===value));}));
  const message=(e:unknown)=>e&&typeof e==='object'&&'message'in e?String(e.message):String(e);
  function accept(value:SettingsSnapshot){snapshot=value;draft=Object.fromEntries(value.fields.filter(f=>f.value!==null).map(f=>[f.key,f.value!]));confirmed=true;}
  async function read(){if(!deviceId)return;const id=deviceId;const current=requests.begin();busy=true;error='';success='';try{const value=await load(id);if(current())accept(value);}catch(e){if(current()){error=message(e);confirmed=false;}}finally{if(current())busy=false;}}
  $effect(()=>{if(!open){resetPanels();busy=false;return;}const scope=`${model}:${deviceId??'none'}`;if(loadedId!==scope){resetPanels();loadedId=scope;mappingLoaded=true;if(deviceId)void read();else busy=false;}});
  async function submit(){if(!deviceId||busy||!dirty||invalid||!confirmed)return;const current=requests.begin();busy=true;discardOpen=false;error='';success='';try{const expected=Object.fromEntries((snapshot?.fields||[]).filter(f=>f.key==='reportRateHz'||f.key==='dpiLevel').map(f=>[f.key==='reportRateHz'?'expectedReportRateHz':'expectedDpiLevel',f.value]));if(snapshot?.stateToken)expected.expectedState=snapshot.stateToken;const values=Object.fromEntries(Object.entries(changes).map(([key,value])=>[key,['lowLatency','macMode','winLock'].includes(key)?value===1:value]));const value=await apply(deviceId,{...values,...expected} as Record<string,SettingValue>);if(!current())return;accept(value);success='设置已写入并读回确认。';}catch(e){if(!current())return;error=`应用失败：${message(e)}。请重新读取核对。`;confirmed=false;}finally{if(current())busy=false;}}
  const describe=(key:string,value:SettingValue|null|undefined)=>settingValueLabel(snapshot?.fields.find(field=>field.key===key),value);
  onDestroy(()=>requests.invalidate());
</script>

<!-- Refactoring UI: physical target and function are primary, confirmed state secondary.
     Existing --ink/--muted/--accent/--control tokens, 8/16/24 spacing; one apply action per editor. -->
{#if open}<Overlay label={`${model}设备设置`} onclose={requestClose}><section class="device-workspace" class:keyboard-workspace={keyboard}>
  <header class="workspace-header" inert={discardOpen}><div><span class="device-badge"><Icon name={keyboard?'keyboard':'mouse'} size={20}/></span><div class="workspace-title"><h2>{model}</h2><span class="connection-status">{sample?'开发样本 · 不连接设备':deviceId?'接收器已连接':'未连接设备'}</span></div><button class="official-settings-link" onclick={official} disabled={sample||!desktop||officialBusy} aria-label={`${model}官方设置`}>官方设置 <Icon name="external" size={14}/></button></div><button use:focusWorkspaceClose class="secondary workspace-close" onclick={requestClose} aria-disabled={busy||!!mappings?.isOperationPending()||extraPending()} aria-label="关闭设备设置"><Icon name="close" size={16}/><span>关闭</span></button></header>
  {#if officialError}<p class="official-error message error" role="alert">{officialError}</p>{/if}
  <div class="workspace-layout" inert={discardOpen}><nav class="workspace-navigation" aria-label="设备设置分类">{#each sections as section}<button class:active={tab===section.id} aria-current={tab===section.id?'page':undefined} onclick={()=>selectSection(section.id)}><Icon name={section.icon} size={16}/>{section.label}</button>{/each}</nav>
  <div class="workspace-content">
    {#if mappingLoaded}<div hidden={tab!=='mapping'}><MappingPanel bind:this={mappings} {deviceId} load={loadMappings} apply={applyMapping} {keyboard} {sample}/></div>{/if}
    {#if dpiLoaded&&!keyboard}<div hidden={tab!=='dpi'}><AtkDpi bind:this={dpi} {deviceId}/></div>{/if}
    {#if macroLoaded&&!keyboard}<div hidden={tab!=='macro'}><AtkMacro bind:this={macro} {deviceId} active={open&&tab==='macro'}/></div>{/if}
    {#if lightingLoaded&&keyboard}<div hidden={tab!=='lighting'}><KeyboardLighting bind:this={lighting} {deviceId}/></div>{/if}
    {#if parametersLoaded&&!keyboard}<div hidden={tab!=='parameters'}><AtkParameters bind:this={parameters} {deviceId}/></div>{/if}
    <div hidden={tab!=='performance'}>
      <div class="editor-heading"><h3>性能设置</h3><p>读取设备当前值，预览后应用。</p></div>
      {#if !snapshot}<div class="settings-empty" role="status"><strong>{busy?'正在读取当前设置…':!deviceId?'连接设备后读取性能设置':'尚未取得性能设置'}</strong><p>读取后显示可调整的字段与设备当前值。</p></div>{/if}
      <div class="settings-fields">{#each visibleFields as field}<div class="setting-field"><div><label for={`setting-${field.key}`}>{field.label}</label><p>{field.description||''}</p>{#if !field.available}<span class="unavailable">{field.reason||'暂不可修改'}</span>{/if}</div><div class="field-control">{#if field.kind==='select'}<select id={`setting-${field.key}`} disabled={!field.available||busy} bind:value={draft[field.key]}><option value={undefined} disabled>未知 / 尚未读取</option>{#each field.options||[] as option}<option value={option.value}>{option.label}</option>{/each}</select>{:else if field.kind==='boolean'}<input id={`setting-${field.key}`} type="checkbox" disabled={!field.available||busy} checked={draft[field.key]===true} onchange={e=>draft[field.key]=e.currentTarget.checked}/>{:else}<input id={`setting-${field.key}`} type="number" min={field.min} max={field.max} step={field.step||1} disabled={!field.available||busy} value={draft[field.key]??''} oninput={e=>draft[field.key]=Number(e.currentTarget.value)}/>{/if}<small>设备读数：{describe(field.key,field.value)}</small></div></div>{/each}</div>
      {#if snapshot&&!visibleFields.length}<p class="settings-intro">此设备没有可显示的性能字段。</p>{/if}
      {#if dirty}<div class="change-preview"><strong>待应用的变更</strong>{#each Object.entries(changes) as [key,value]}<p>{snapshot?.fields.find(f=>f.key===key)?.label} <span>{describe(key,snapshot?.fields.find(f=>f.key===key)?.value)} → {describe(key,value)}</span></p>{/each}</div>{/if}
      {#if error}<p role="alert" class="message error">{error}</p>{/if}{#if success}<p role="status" class="settings-success">✓ {success}</p>{/if}
      <div class="settings-actions"><span role="status">{busy?'正在与设备通信…':!confirmed&&dirty?'请先撤回预览，再重新读取核对。':invalid?'请选择允许范围内的参数':dirty?'性能预览尚未应用':snapshot?.sampledAt?`最近读取 ${new Date(snapshot.sampledAt).toLocaleTimeString('zh-CN')}`:'设备当前设置尚未知'}</span><button class="secondary" disabled={!deviceId||busy||dirty} onclick={read}>重新读取</button><button class="secondary" disabled={!dirty||busy} onclick={()=>{if(snapshot){const wasConfirmed=confirmed;accept(snapshot);confirmed=wasConfirmed;}}}>撤回预览</button><button class="primary" disabled={!deviceId||!dirty||busy||invalid||!confirmed} onclick={submit}>{busy?'等待设备确认…':'应用到设备'}</button></div>
    </div>
    <div hidden={tab!=='profiles'} class="settings-placeholder"><h3>配置管理</h3><p>板载配置切换、导入 / 导出、恢复默认</p><span>待补：尚无经过核实的完整配置写入与恢复接口。</span></div>
    <div hidden={tab!=='other'} class="settings-placeholder"><h3>其他设置</h3>{#if keyboard}<div class="feature-row"><div><strong>宏与快捷指令录制</strong><p>KX75 宏区协议尚未核实，保留现有设备数据。</p></div><span>待补</span></div>{/if}<div class="feature-row"><div><strong>恢复默认设置</strong><p>完整原值备份与恢复协议尚待核实。</p></div><span>待补</span></div></div>
  </div></div>
  {#if discardOpen}<div class="discard-shade"><div class="discard-prompt" role="alertdialog" aria-modal="true" aria-label="放弃未应用改动" tabindex="-1" onkeydown={e=>{if(e.key==='Escape'){e.preventDefault();e.stopPropagation();continueEditing();}}}><strong>还有未应用的改动</strong><p>关闭将放弃设备设置中的全部预览。</p><div><button bind:this={continueButton} class="secondary" onclick={continueEditing}>继续编辑</button><button class="secondary" onclick={finishClose}>放弃并关闭</button></div></div></div>{/if}
</section></Overlay>{/if}
<style>
  /* §2.1 / §3.6: navigation, editor and one apply bar form distinct groups. */
  :global(dialog:has(.device-workspace)){width:100vw;height:100dvh;padding:16px;inset:0;margin:0;align-items:center;justify-content:center;max-width:none;overflow:hidden}
  :global(dialog:has(.device-workspace) .overlay-surface){padding:0;width:min(1120px,100%);max-width:none;max-height:calc(100dvh - 32px);overflow:hidden;background:var(--glass-tint,none),var(--glass-overlay,var(--overlay));border-color:var(--glass-edge,var(--line));box-shadow:var(--glass-overlay-shadow);backdrop-filter:blur(var(--glass-blur,16px))}
  .device-workspace{position:relative;width:100%;height:min(760px,calc(100dvh - 32px));display:flex;flex-direction:column;min-height:0;color:var(--ink);font-family:inherit;overflow:hidden}
  .workspace-header{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-shrink:0;padding:16px 24px;border-bottom:1px solid var(--quiet-line);background:var(--glass-chrome,var(--control))}
  .workspace-header>div{display:flex;align-items:center;gap:12px;min-width:0}.workspace-title{min-width:0}.workspace-header h2{margin:0;font-size:16px;font-weight:600;line-height:1.5;overflow-wrap:anywhere}.connection-status{display:block;font-size:12px;color:var(--muted);line-height:1.5}.device-badge{display:flex;align-items:center;justify-content:center;width:40px;height:40px;flex:none;border:1px solid var(--quiet-line);border-radius:12px;background:var(--glass-panel,var(--surface));color:var(--muted)}
  .official-settings-link{display:inline-flex;align-items:center;gap:4px;border:0;background:transparent;color:var(--accent);font-size:12px;white-space:nowrap;padding:8px;margin-left:8px}.official-settings-link:hover:not(:disabled){text-decoration:underline}.official-settings-link:disabled{color:var(--muted)}.official-error{margin:0;padding:12px 24px}.workspace-close{display:inline-flex;align-items:center;gap:8px;flex:none}
  .workspace-close[aria-disabled=true]{color:var(--muted);cursor:wait}
  .workspace-layout{display:grid;grid-template-columns:168px minmax(0,1fr);flex:1;min-height:0;overflow:hidden}.workspace-navigation{display:flex;flex-direction:column;gap:4px;padding:16px 8px;background:var(--glass-chrome,var(--control));border-right:1px solid var(--quiet-line);overflow:auto}.workspace-navigation button{display:flex;align-items:center;gap:12px;min-height:40px;border:1px solid transparent;border-radius:8px;padding:8px 12px;background:transparent;color:var(--muted);font:inherit;font-size:12px;text-align:left;white-space:nowrap}.workspace-navigation button.active{background:var(--glass-panel,var(--surface));border-color:var(--glass-edge,var(--line));color:var(--accent);font-weight:600}.workspace-navigation button:hover:not(.active){background:var(--control)}.workspace-content{padding:24px;min-width:0;min-height:0;overflow:auto;overscroll-behavior:contain;background:var(--glass-panel,var(--surface))}
  .editor-heading h3,.settings-placeholder h3{font-size:16px;font-weight:600;margin:0 0 8px}.editor-heading p,.settings-placeholder p,.settings-placeholder>span{font-size:12px;color:var(--muted);line-height:1.65}.settings-placeholder{padding:16px 0;min-height:240px}.feature-row{display:flex;justify-content:space-between;align-items:flex-start;gap:16px;padding:24px 0;border-bottom:1px solid var(--quiet-line)}.feature-row strong{font-size:14px}.feature-row p{margin:8px 0 0}.feature-row>span{font-size:12px;color:var(--muted);white-space:nowrap}.settings-fields{max-width:720px}.field-control{max-width:280px;min-width:140px}.field-control small{display:block;margin-top:8px;color:var(--muted);font-size:12px}.unavailable{font-size:12px;color:var(--muted)}
  /* §8.4 / §5.7: unknown and pending states remain explicit at every width. */
  .device-workspace :global(.settings-empty){padding:24px;border:1px dashed var(--line);border-radius:12px;background:var(--control);margin:16px 0}.device-workspace :global(.settings-empty strong){font-size:14px;font-weight:600}.device-workspace :global(.settings-empty p){font-size:12px;color:var(--muted);line-height:1.65;margin:8px 0 0}.device-workspace :global(.settings-intro){font-size:12px;line-height:1.65;color:var(--muted);margin:12px 0}.device-workspace :global(.change-preview){padding:16px;margin:16px 0;border:1px solid var(--warning);border-radius:12px;background:var(--warning-soft);color:var(--warning);font-size:12px;line-height:1.65;overflow-wrap:anywhere}.device-workspace :global(.change-preview strong){font-weight:600}.device-workspace :global(.change-preview p){margin:8px 0 0}.device-workspace :global(.settings-success){padding:12px 16px;border-radius:8px;color:var(--success);background:var(--success-soft);font-size:12px;line-height:1.65}.device-workspace :global(.message.error){color:var(--danger);background:var(--danger-soft);padding:12px 16px;border-radius:8px;font-size:12px;line-height:1.65;overflow-wrap:anywhere}
  .device-workspace :global(.settings-actions){position:sticky;bottom:-24px;z-index:2;display:flex;flex-wrap:wrap;align-items:center;justify-content:flex-end;gap:8px;margin:24px -0px -0px;padding:16px 0;background:var(--glass-panel,var(--surface));border-top:1px solid var(--quiet-line)}.device-workspace :global(.settings-actions>span){display:block;flex:1 1 100%;min-width:0;width:auto;margin:0;color:var(--muted);font-size:12px;line-height:1.5;white-space:normal;overflow:visible;text-overflow:clip}.device-workspace :global(.settings-actions>span:empty){display:none}.device-workspace :global(.settings-actions button){flex:0 1 auto;width:auto;max-width:100%;min-height:36px;padding:8px 12px;margin:0;font-size:12px;white-space:normal}.device-workspace :global(.settings-actions .primary){width:auto;margin:0;background:var(--primary-bg);color:var(--on-primary)}.device-workspace :global(.setting-field){padding:16px 0}
  .discard-shade{position:absolute;inset:0;z-index:5;display:flex;align-items:center;justify-content:center;padding:24px;background:var(--glass-chrome,var(--control))}.discard-prompt{width:min(100%,400px);padding:24px;border:1px solid var(--line);border-radius:16px;background:var(--glass-overlay,var(--overlay));box-shadow:var(--glass-overlay-shadow)}.discard-prompt strong{font-size:16px;font-weight:600}.discard-prompt p{font-size:13px;color:var(--muted);line-height:1.65;margin:12px 0 24px}.discard-prompt>div{display:flex;flex-wrap:wrap;gap:8px;justify-content:flex-end}
  @media(max-width:760px){.workspace-layout{display:flex;flex-direction:column}.workspace-navigation{flex-direction:row;flex-shrink:0;flex-wrap:nowrap;padding:8px;border-right:0;border-bottom:1px solid var(--quiet-line)}.workspace-navigation button{flex:none;gap:8px}.workspace-content{flex:1;padding:16px}.workspace-header{padding:12px 16px}.device-workspace :global(.settings-actions){bottom:-16px}.official-settings-link{margin:0}.workspace-header>div{gap:8px}.device-badge{display:none}}
  @media(max-width:450px){:global(dialog:has(.device-workspace)){padding:8px}:global(dialog:has(.device-workspace) .overlay-surface){max-height:calc(100dvh - 16px)}.device-workspace{height:calc(100dvh - 16px)}.workspace-header{padding:12px}.workspace-header h2{font-size:14px}.workspace-close{padding:8px}.workspace-close span{display:none}.connection-status{font-size:12px}.official-settings-link{padding:8px 4px;font-size:12px}.workspace-content{padding:16px 12px}.workspace-navigation button{padding:8px}.device-workspace :global(.settings-actions){bottom:-16px;gap:8px}.device-workspace :global(.settings-actions button){flex:1 1 auto;padding:8px}.device-workspace :global(.settings-actions .primary){flex:1 1 100%}.setting-field{align-items:flex-start;flex-direction:column;gap:12px}.field-control{max-width:none;width:100%}.discard-shade{padding:16px}.discard-prompt{padding:24px 16px}}
</style>
